-- subcategory 값 채우기 (0009_product_subcategory.sql 실행 후 진행)
-- 반드시 0009 먼저 실행해서 subcategory 컬럼이 생긴 뒤에 이 파일을 실행하세요.

-- 1) 패들: Champion(초급)/Edge(중급)/Pro(고급)
-- 근거: joola.com 공식 사이트가 패들을 recreational(Champion 라인)/performance(Edge 라인)/professional(Pro IV·V 라인) 3단계로 태깅하고 있음
update products set subcategory = case
  when name ilike '%champion%' then 'Champion'
  when name ilike '%edge%' then 'Edge'
  when name ilike '%cfs%' or name ilike '%cgs%' or name ilike '%cas%' or name ilike '%cds%' or name ilike '%fds%'
    or name ilike '%dual%' or name ilike '%vision%' then 'Edge'
  when name ilike '%pro v%' or name ilike '%pro iv%' or name ilike '%3s%' then 'Pro'
  when unit_price >= 259000 then 'Pro'
  when unit_price >= 140000 then 'Edge'
  else 'Champion'
end
where category = '패들';

-- 2) 액세서리 세분화
update products set subcategory = case
  when name ilike '%edge guard%' or name ilike '%edge tape%' then '그립테이프'
  when name ilike '%keychain%' then '키체인'
  when name ilike '%paddle cover%' or name ilike '%neoprene cover%' then '파들커버'
  when name ilike '%grip%' then '그립'
  when name ilike '%towel%' then '타월'
  when name ilike '%ball%' then '공'
  when name ilike '%net%' then '네트'
  when name ilike '%wristband%' or name ilike '%luggage tag%' then '기타소품'
  else '기타'
end
where category = '액세서리';

-- 3) 의류: 남성/여성 (joola.com 공식 상품명/태그의 Men's·Women's 표기를 SKU 기준으로 매칭 — 487개 중 363개 매칭됨)
